package com.maidaibridge.action.impl;
import com.maidaibridge.action.AbstractMaidAction;import com.maidaibridge.action.ActionContext;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.item.Item;import net.minecraft.world.item.ItemStack;
public final class EquipAction extends AbstractMaidAction {private final Item item;private final EquipmentSlot slot;public EquipAction(String req,int timeout,Item item,EquipmentSlot slot){this(req,"equip",timeout,item,slot);}public EquipAction(String req,String type,int timeout,Item item,EquipmentSlot slot){super(req,type,timeout);this.item=item;this.slot=slot;}@Override protected void onTick(ActionContext ctx){ItemStack next=ctx.inventory().extract(ctx.maid(),item,1,false);if(next.isEmpty()){fail("NO_MATERIAL");return;}ItemStack old=ctx.maid().getItemBySlot(slot).copy();ctx.maid().setItemSlot(slot,next);if(!old.isEmpty()&&!ctx.inventory().insert(ctx.maid(),old)){ctx.maid().spawnAtLocation(old);}succeed("EQUIPPED");}}
